def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = 18.0 if hp > 3 else 42.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_prev_bids = []
    weak_opp_count = 0
    rich_opp_count = 0

    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            opp_hp = float(opp.get('hp', 0))
            opp_nwd = int(opp.get('no_water_days', 0))
            if opp_hp <= 3 or opp_nwd >= 1:
                urgent_prev_bids.append(bid)
        if float(opp.get('hp', 0)) <= 3:
            weak_opp_count += 1
        if float(opp.get('budget', 0)) >= 400:
            rich_opp_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    urgent_high = max(urgent_prev_bids) if urgent_prev_bids else highest_prev

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    low_supply = supply <= 17.0
    high_supply = supply >= 22.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    if day >= 8:
        danger += 1

    if danger >= 5:
        bid = max(urgent_high + 3.0, 0.92 * DAILY_SALARY)
        if low_supply:
            bid = max(bid, highest_prev + 6.0)
        return float(max(0.0, min(budget, bid)))

    if danger >= 3:
        bid = max(urgent_high + 2.0, 0.72 * DAILY_SALARY)
        if low_supply:
            bid = max(bid, highest_prev + 4.0)
        if high_supply:
            bid *= 0.9
        return float(max(0.0, min(budget, bid)))

    if low_supply:
        if highest_prev >= 120.0:
            bid = min(highest_prev + 1.5, 0.78 * DAILY_SALARY)
        else:
            bid = 0.6 * DAILY_SALARY
        if rich_opp_count >= 2:
            bid += 4.0
        return float(max(0.0, min(budget, bid)))

    if high_supply:
        bid = 0.24 * DAILY_SALARY
        if weak_opp_count >= 2:
            bid = 0.18 * DAILY_SALARY
        return float(max(0.0, min(budget, bid)))

    bid = 0.42 * DAILY_SALARY
    if highest_prev > 0:
        target = highest_prev * 0.42
        bid = max(bid, min(target, 0.58 * DAILY_SALARY))
    if rich_opp_count >= 2:
        bid += 3.0

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 40.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]
    avg_opp_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 120.0
    if my_status['hp'] <= 3:
        return min(my_status['budget'], avg_opp_bid + 10.0)
    if day_context['supply'] < WATER_REQ * 2:
        return min(my_status['budget'], avg_opp_bid + 5.0)
    return min(my_status['budget'], max(DAILY_SALARY * 1.1, avg_opp_bid * 0.8))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Yesterday highest bid among alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    highest_prev = max(yesterday_bids) if yesterday_bids else 0

    # Base bid: percentage of salary depending on urgency
    if hp <= 2:
        base = DAILY_SALARY * 1.0
    elif hp <= 4:
        base = DAILY_SALARY * 0.8
    elif no_water_days >= 1:
        base = DAILY_SALARY * 0.7
    else:
        base = DAILY_SALARY * 0.6

    # Adjust for supply scarcity
    if supply < 18:
        base *= 1.2
    elif supply > 22:
        base *= 0.85

    # Exploit yesterday's high bidders: if they bid very high, they may have less budget now, so we can bid lower
    if highest_prev > DAILY_SALARY * 1.2:
        if hp > 3:
            base = min(base, DAILY_SALARY * 0.5)
        else:
            base = max(base, DAILY_SALARY * 0.9)

    # Ensure not to exceed budget and reasonable range
    bid = min(budget, max(DAILY_SALARY * 0.4, base))
    return int(bid)
